"""Unlabeled triangle-free pair graphs on eight singleton labels, generated by canonical one-edge augmentation. A repeated pair violates cap 3 on two labels; a triangle violates cap 5 on three. Test induced <=4 demands among the fixed cells and each extra cell before completing six residual rows. For cubic graphs enumerate completions exactly. Negative induced tests never presume red adjacencies outside the fixed cells."""
import igraph as ig,itertools,json,collections,sys
from ramsey_unsaturated_free_six_gate import P,CardEnc,Solver
from ramsey_unsaturated_archive_ladder import run
pairs=itertools.combinations;V=range(8);cap=(0,1,3,5,8,12,16,19,26);single=[1<<i for i in V]
def graphs(edge_count=12):
 level={()}
 for d in range(edge_count):
  nxt=set()
  for es in level:
   g=ig.Graph(8,list(es));a=[set(g.neighbors(i)) for i in V]
   for i,j in pairs(V,2):
    if j in a[i] or a[i]&a[j]:continue
    z=g.copy();z.add_edge(i,j);nxt.add(tuple(sorted(z.permute_vertices(z.canonical_permutation()).get_edgelist())))
  level=nxt
 return sorted(level)
def local(m):
 N=len(m);E={p:i+1 for i,p in enumerate(p for p in pairs(range(N),2) if not m[p[0]]&m[p[1]])};cs=[]
 for t in range(256):
  vs=[i for i,x in enumerate(m) if not x&~t];k=t.bit_count()
  if len(vs)>cap[k]:return False
  if k<=4:
   for s in pairs(vs,k+1):
    c=[E[p] for p in pairs(s,2) if p in E]
    if not c:return False
    cs.append(c)
 for x in pairs(range(N),3):
  es=list(pairs(x,2));
  if all(p in E for p in es):cs.append([-E[p] for p in es])
 with Solver(name='cadical195',bootstrap_with=cs) as sl:return sl.solve()
def screen(es):
 g=ig.Graph(8,list(es));deg=g.degree();f=tuple(single+[1<<i|1<<j for i,j in es]);z=dict(edges=es,degrees=sorted(deg),base=local(f));
 if not z['base']:return z
 G=[[sum(1<<p[i] for i in V if s>>i&1) for s in range(256)] for p in g.get_automorphisms_vf2()];seen=set();opts=[]
 for s in range(1,256):
  if s in seen:continue
  orbit={p[s] for p in G};seen.update(orbit)
  if local(f+(s,)):opts.extend(orbit)
 opts.sort();z.update(allowed=len(opts),small=[s for s in opts if s.bit_count()<4]);
 if not opts:return z
 if not exhaustive:return z
 # Since we need 24 incidences, smallest allowed size 4 forces all sizes 4. Else prune by residual row marginals at every step.
 if not z['small']:opts=[s for s in opts if s.bit_count()==4]
 todo=[6-d for d in deg];hist=collections.Counter();surv=[];checked=0
 def rec(t,lo,left):
  nonlocal checked
  if not left:
   checked+=1;r=run(f+t);hist[r[0]]+=1
   if r[0] not in ('forced4','unsat4'):surv.append(dict(t=t,gate=r))
   return
  must=sum(1<<i for i,d in enumerate(todo) if d==left);can=sum(1<<i for i,d in enumerate(todo) if d>0)
  for j in range(lo,len(opts)):
   s=opts[j]
   if must&~s or s&~can:continue
   u=t+(s,)
   if any(tuple(sorted(p[x] for x in u))<u for p in G):continue
   if left>1 and len(u)>1 and not local(f+u):continue
   for i in V:todo[i]-=s>>i&1
   rec(u,j,left-1)
   for i in V:todo[i]+=s>>i&1
 if all(0<=v<=6 for v in todo):rec((),0,6)
 z.update(full=checked,hist=hist,surv=surv);return z
exhaustive=False
if __name__=='__main__':
 from concurrent.futures import ProcessPoolExecutor
 gs=graphs();print('12-edge types',len(gs),flush=True);rs=[]
 with ProcessPoolExecutor(6) as ex:
  for z in ex.map(screen,gs):rs.append(z);print(z['degrees'],z['base'],len(z.get('small',[])),z.get('hist'),flush=True);(P/'ramsey_unsaturated_pair_graphs.json').write_text(json.dumps(rs)+'\n')
